// `succeeded` means the operation took effect. `rejected` means the request was refused with an
// actionable 4xx error. `failed` means the platform failed to complete it (5xx).
// Ref: #/components/schemas/Outcome
type Outcome string

const (
	OutcomeSucceeded Outcome = "succeeded"
	OutcomeRejected  Outcome = "rejected"
	OutcomeFailed    Outcome = "failed"
)

// AllValues returns all Outcome values.
func (Outcome) AllValues() []Outcome {
	return []Outcome{
		OutcomeSucceeded,
		OutcomeRejected,
		OutcomeFailed,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s Outcome) MarshalText() ([]byte, error) {
	switch s {
	case OutcomeSucceeded:
		return []byte(s), nil
	case OutcomeRejected:
		return []byte(s), nil
	case OutcomeFailed:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *Outcome) UnmarshalText(data []byte) error {
	switch Outcome(data) {
	case OutcomeSucceeded:
		*s = OutcomeSucceeded
		return nil
	case OutcomeRejected:
		*s = OutcomeRejected
		return nil
	case OutcomeFailed:
		*s = OutcomeFailed
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}
